import React from 'react';

export default function LmsDashboard({ username, onLogout }) {
  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f4f7f6' }}>
      
      <div style={{ width: '250px', backgroundColor: '#2e7d32', color: '#fff', padding: '20px' }}>
        <h2 style={{ fontSize: '20px', marginBottom: '40px' }}>Admin Panel</h2>
        <ul style={{ listStyle: 'none', padding: 0 }}>
          <li style={{ marginBottom: '20px', cursor: 'pointer' }}>Dashboard</li>
          <li style={{ marginBottom: '20px', cursor: 'pointer' }} onClick={onLogout}>Logout</li>
        </ul>
      </div>

      <div style={{ flex: 1, padding: '40px' }}>
        <h1>Welcome, {username}!</h1>
        <p>This is your admin dashboard.</p>
      </div>
      
    </div>
  );
}
